//! Minimal Floem app for OpenHarmony (HarmonyOS).
//!
//! Unlike Android (`android_main`) or iOS (`UIApplicationMain` reached through
//! winit), OpenHarmony starts the UI from ArkTS (`EntryAbility` / XComponent).
//! The Rust side therefore exposes two FFI surfaces:
//!
//! 1. A **C-ABI runtime entry** generated by
//!    [`tgui_winit_ohos::export_ohos_winit_app!`] — the `ohos_winit_runtime_*`
//!    symbols the ArkTS/NAPI layer calls to drive the winit event loop.
//! 2. **N-API bridges** (`register_platform_bridge`, `on_file_picked`,
//!    `on_shared_files`, `on_accessibility_action`) that ArkTS calls *back*
//!    into (see `entry/src/main/ets/FloemBridge.ets`).
//!
//! The runtime entry only needs a *factory*: a function that builds a
//! [`floem::Application`] with at least one window. The OHOS runtime drains
//! `initial_windows` inside `can_create_surfaces`.
//!
//! ```bash
//! # Build & package with cargo-ohos-app (see README.md), then run on a
//! # device or the OHOS emulator.
//! cargo ohos --target aarch64-unknown-linux-ohos
//! ```

#[cfg(target_env = "ohos")]
tgui_winit_ohos::export_ohos_winit_app!(ohos_factory);

#[cfg(target_env = "ohos")]
fn ohos_factory() -> floem::Application {
    // `floem_app_factory()` in floem core returns an `Application` with *no*
    // window; apps must build their own factory that also calls `.window(...)`
    // so the OHOS runtime has something to surface.
    floem::Application::new_ohos(floem::AppConfig::default()).window(|_id| app_view(), None)
}

#[cfg(target_env = "ohos")]
fn app_view() -> impl floem::view::IntoView {
    use floem::prelude::*;
    let counter = RwSignal::new(0);
    let text = RwSignal::new(String::new());

    Stack::vertical((
        // A small counter to prove pointer input + redraw work.
        Stack::horizontal((
            Button::new("+").action(move || counter.update(|v| *v += 1)),
            Label::derived(move || format!("Value: {}", counter.get())),
            Button::new("-").action(move || counter.update(|v| *v -= 1)),
        ))
        .style(|s| s.gap(10.0)),
        // A text field — exercises the OHOS IME / soft keyboard bridge.
        TextInput::new(text),
        Label::derived(move || format!("You typed: {}", text.get())),
    ))
    .style(|s| {
        s.size_full()
            .flex_col()
            .items_center()
            .justify_center()
            .gap(12.0)
    })
}
